CREATE POLICY affiliate_referrals_write ON public.affiliate_referrals FOR ALL TO authenticated USING (has_org_role(organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER','DRIVER_MANAGER','ACCOUNTANT'])) WITH CHECK (has_org_role(organization_id, ARRAY['SUPER_ADMIN','ORGANIZATION_ADMIN','BRANCH_MANAGER','FLEET_MANAGER','DRIVER_MANAGER','ACCOUNTANT']));